ore int NULL,
 CONSTRAINT xpktirociniodiario PRIMARY KEY (idtirociniodiario,
idtirocinioprogetto,
idtirociniocandidatura,
idtirocinioproposto,
idreg_referente,
idreg_studenti
)
)
END
