-- CREAZIONE VISTA appellodefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[appellodefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[appellodefaultview]
GO

CREATE VIEW [dbo].[appellodefaultview] AS SELECT  appello.aa, appello.basevoto AS appello_basevoto, appello.cftoend AS appello_cftoend, appello.ct AS appello_ct, appello.cu AS appello_cu, appello.description, appello.esteroend AS appello_esteroend, appello.esterostart AS appello_esterostart, appello.idappello, [dbo].appelloazionekind.title AS appelloazionekind_title, appello.idappelloazionekind AS appello_idappelloazionekind, [dbo].appellokind.title AS appellokind_title, appello.idappellokind AS appello_idappellokind, [dbo].sessionekind.title AS sessionekind_title, [dbo].sessione.start AS sessione_start, [dbo].sessione.stop AS sessione_stop, appello.idsessione, [dbo].studprenotkind.title AS studprenotkind_title, appello.idstudprenotkind AS appello_idstudprenotkind,CASE WHEN appello.lavoratori = 'S' THEN 'Si' WHEN appello.lavoratori = 'N' THEN 'No' END AS appello_lavoratori, appello.lt AS appello_lt, appello.lu AS appello_lu, appello.minanniiscr AS appello_minanniiscr, appello.minvoto AS appello_minvoto,CASE WHEN appello.passaggio = 'S' THEN 'Si' WHEN appello.passaggio = 'N' THEN 'No' END AS appello_passaggio, appello.penotend AS appello_penotend, appello.posti AS appello_posti, appello.prenotstart AS appello_prenotstart,CASE WHEN appello.prointermedia = 'S' THEN 'Si' WHEN appello.prointermedia = 'N' THEN 'No' END AS appello_prointermedia,CASE WHEN appello.publicato = 'S' THEN 'Si' WHEN appello.publicato = 'N' THEN 'No' END AS appello_publicato, appello.surmanestop AS appello_surmanestop, appello.surnamestart AS appello_surnamestart, isnull('Descrizione: ' + appello.description + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].sessionekind.title + '; ','') + ' ' + isnull('Anno accademico: ' + appello.aa + '; ','') as dropdown_title FROM [dbo].appello WITH (NOLOCK)  LEFT OUTER JOIN [dbo].appelloazionekind WITH (NOLOCK) ON appello.idappelloazionekind = [dbo].appelloazionekind.idappelloazionekind LEFT OUTER JOIN [dbo].appellokind WITH (NOLOCK) ON appello.idappellokind = [dbo].appellokind.idappellokind LEFT OUTER JOIN [dbo].sessione WITH (NOLOCK) ON appello.idsessione = [dbo].sessione.idsessione LEFT OUTER JOIN [dbo].sessionekind WITH (NOLOCK) ON sessione.idsessionekind = [dbo].sessionekind.idsessionekind LEFT OUTER JOIN [dbo].studprenotkind WITH (NOLOCK) ON appello.idstudprenotkind = [dbo].studprenotkind.idstudprenotkind WHERE  appello.idappello IS NOT NULL 
GO

