-- CREAZIONE VISTA aulakinddefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[aulakinddefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[aulakinddefaultview]
GO

CREATE VIEW [dbo].[aulakinddefaultview] AS SELECT CASE WHEN aulakind.active = 'S' THEN 'Si' WHEN aulakind.active = 'N' THEN 'No' END AS aulakind_active, aulakind.ct AS aulakind_ct, aulakind.cu AS aulakind_cu, aulakind.description AS aulakind_description, aulakind.idaulakind, aulakind.lt AS aulakind_lt, aulakind.lu AS aulakind_lu, aulakind.sortcode AS aulakind_sortcode, aulakind.title, isnull('Tipologia: ' + aulakind.title + '; ','') as dropdown_title FROM [dbo].aulakind WITH (NOLOCK)  WHERE  aulakind.idaulakind IS NOT NULL 
GO

