-- CREAZIONE VISTA aulaseg_childview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[aulaseg_childview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[aulaseg_childview]
GO

CREATE VIEW [dbo].[aulaseg_childview] AS SELECT  aula.address AS aula_address, aula.cap AS aula_cap, aula.capienza AS aula_capienza, aula.capienzadis AS aula_capienzadis, aula.code AS aula_code, aula.ct AS aula_ct, aula.cu AS aula_cu, aula.dotazioni AS aula_dotazioni, aula.idaula, [dbo].aulakind.title AS aulakind_title, aula.idaulakind AS aula_idaulakind, [dbo].geo_city.title AS geo_city_title, aula.idcity, aula.idedificio, [dbo].geo_nation.title AS geo_nation_title, aula.idnation, aula.idsede, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, aula.idstruttura, aula.latitude AS aula_latitude, aula.location AS aula_location, aula.longitude AS aula_longitude, aula.lt AS aula_lt, aula.lu AS aula_lu, aula.title, isnull('Denominazione: ' + aula.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].aula WITH (NOLOCK)  LEFT OUTER JOIN [dbo].aulakind WITH (NOLOCK) ON aula.idaulakind = [dbo].aulakind.idaulakind LEFT OUTER JOIN [dbo].geo_city WITH (NOLOCK) ON aula.idcity = [dbo].geo_city.idcity LEFT OUTER JOIN [dbo].geo_nation WITH (NOLOCK) ON aula.idnation = [dbo].geo_nation.idnation LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON aula.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  aula.idaula IS NOT NULL  AND aula.idedificio IS NOT NULL  AND aula.idsede IS NOT NULL 
GO

