-- CREAZIONE VISTA bandodsserviziosegview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[bandodsserviziosegview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[bandodsserviziosegview]
GO

CREATE VIEW [dbo].[bandodsserviziosegview] AS SELECT CASE WHEN bandodsservizio.alloggio = 'S' THEN 'Si' WHEN bandodsservizio.alloggio = 'N' THEN 'No' END AS bandodsservizio_alloggio, bandodsservizio.borsafuorisede AS bandodsservizio_borsafuorisede, bandodsservizio.borsainsede AS bandodsservizio_borsainsede, bandodsservizio.borsapendolari AS bandodsservizio_borsapendolari, bandodsservizio.contributo AS bandodsservizio_contributo, bandodsservizio.contributomiimporto AS bandodsservizio_contributomiimporto, bandodsservizio.contributomimesi AS bandodsservizio_contributomimesi, bandodsservizio.ct AS bandodsservizio_ct, bandodsservizio.cu AS bandodsservizio_cu,CASE WHEN bandodsservizio.fuoricorso = 'S' THEN 'Si' WHEN bandodsservizio.fuoricorso = 'N' THEN 'No' END AS bandodsservizio_fuoricorso, bandodsservizio.idbandods, bandodsservizio.idbandodsservizio, [dbo].bandodsserviziokind.title AS bandodsserviziokind_title, [dbo].bandodsserviziokind.description AS bandodsserviziokind_description, bandodsservizio.idbandodsserviziokind AS bandodsservizio_idbandodsserviziokind, [dbo].esonero.title AS esonero_title, bandodsservizio.idesonero, istattitolistudiomin.titolo AS istattitolistudiomin_titolo, bandodsservizio.idistattitolistudio_min AS bandodsservizio_idistattitolistudio_min, bandodsservizio.iseemax AS bandodsservizio_iseemax, bandodsservizio.ispemax AS bandodsservizio_ispemax, bandodsservizio.lt AS bandodsservizio_lt, bandodsservizio.lu AS bandodsservizio_lu,CASE WHEN bandodsservizio.maggiorenne = 'S' THEN 'Si' WHEN bandodsservizio.maggiorenne = 'N' THEN 'No' END AS bandodsservizio_maggiorenne,CASE WHEN bandodsservizio.mensa = 'S' THEN 'Si' WHEN bandodsservizio.mensa = 'N' THEN 'No' END AS bandodsservizio_mensa,CASE WHEN bandodsservizio.parttime = 'S' THEN 'Si' WHEN bandodsservizio.parttime = 'N' THEN 'No' END AS bandodsservizio_parttime,CASE WHEN bandodsservizio.primaimmatlivello = 'S' THEN 'Si' WHEN bandodsservizio.primaimmatlivello = 'N' THEN 'No' END AS bandodsservizio_primaimmatlivello FROM [dbo].bandodsservizio WITH (NOLOCK)  LEFT OUTER JOIN [dbo].bandodsserviziokind WITH (NOLOCK) ON bandodsservizio.idbandodsserviziokind = [dbo].bandodsserviziokind.idbandodsserviziokind LEFT OUTER JOIN [dbo].esonero WITH (NOLOCK) ON bandodsservizio.idesonero = [dbo].esonero.idesonero LEFT OUTER JOIN [dbo].istattitolistudio AS istattitolistudiomin WITH (NOLOCK) ON bandodsservizio.idistattitolistudio_min = istattitolistudiomin.idistattitolistudio WHERE  bandodsservizio.idbandods IS NOT NULL  AND bandodsservizio.idbandodsservizio IS NOT NULL 
GO

