-- CREAZIONE VISTA bandomisegview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[bandomisegview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[bandomisegview]
GO

CREATE VIEW [dbo].[bandomisegview] AS SELECT  bandomi.aa, bandomi.cfminimi AS bandomi_cfminimi, bandomi.codice AS bandomi_codice, bandomi.ct AS bandomi_ct, bandomi.cu AS bandomi_cu, bandomi.datariferimentorequisiti AS bandomi_datariferimentorequisiti, bandomi.durata AS bandomi_durata, [dbo].accordoscambiomi.title AS accordoscambiomi_title, bandomi.idaccordoscambiomi AS bandomi_idaccordoscambiomi, [dbo].assicurazione.societaassicura AS assicurazione_societaassicura, [dbo].assicurazione.datascadenza AS assicurazione_datascadenza, bandomi.idassicurazione, bandomi.idbandomi, [dbo].bandomobilitaintkind.title AS bandomobilitaintkind_title, bandomi.idbandomobilitaintkind AS bandomi_idbandomobilitaintkind, [dbo].duratakind.title AS duratakind_title, bandomi.idduratakind AS bandomi_idduratakind, [dbo].graduatoria.title AS graduatoria_title, bandomi.idgraduatoria, [dbo].programmami.acronimo AS programmami_acronimo, bandomi.idprogrammami AS bandomi_idprogrammami, [dbo].residence.description AS residence_description, bandomi.idresidence, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, bandomi.idstruttura,CASE WHEN bandomi.iscrittonellanno = 'S' THEN 'Si' WHEN bandomi.iscrittonellanno = 'N' THEN 'No' END AS bandomi_iscrittonellanno, bandomi.lt AS bandomi_lt, bandomi.lu AS bandomi_lu, bandomi.maxpreferenze AS bandomi_maxpreferenze, bandomi.mediaminima AS bandomi_mediaminima,CASE WHEN bandomi.nessundebito = 'S' THEN 'Si' WHEN bandomi.nessundebito = 'N' THEN 'No' END AS bandomi_nessundebito, bandomi.numeroesamiminimo AS bandomi_numeroesamiminimo, bandomi.startcandidature AS bandomi_startcandidature, bandomi.startgraduatoria AS bandomi_startgraduatoria, bandomi.startpermanenza AS bandomi_startpermanenza, bandomi.startpresentazione AS bandomi_startpresentazione, bandomi.stopcadidature AS bandomi_stopcadidature, bandomi.stopgraduatoria AS bandomi_stopgraduatoria, bandomi.stoppermanenza AS bandomi_stoppermanenza, bandomi.stoppresentazione AS bandomi_stoppresentazione, bandomi.testodomanda AS bandomi_testodomanda, bandomi.title, bandomi.titolodomanda AS bandomi_titolodomanda, isnull('Titolo del bando: ' + bandomi.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].bandomi WITH (NOLOCK)  LEFT OUTER JOIN [dbo].accordoscambiomi WITH (NOLOCK) ON bandomi.idaccordoscambiomi = [dbo].accordoscambiomi.idaccordoscambiomi LEFT OUTER JOIN [dbo].assicurazione WITH (NOLOCK) ON bandomi.idassicurazione = [dbo].assicurazione.idassicurazione LEFT OUTER JOIN [dbo].bandomobilitaintkind WITH (NOLOCK) ON bandomi.idbandomobilitaintkind = [dbo].bandomobilitaintkind.idbandomobilitaintkind LEFT OUTER JOIN [dbo].duratakind WITH (NOLOCK) ON bandomi.idduratakind = [dbo].duratakind.idduratakind LEFT OUTER JOIN [dbo].graduatoria WITH (NOLOCK) ON bandomi.idgraduatoria = [dbo].graduatoria.idgraduatoria LEFT OUTER JOIN [dbo].programmami WITH (NOLOCK) ON bandomi.idprogrammami = [dbo].programmami.idprogrammami LEFT OUTER JOIN [dbo].residence WITH (NOLOCK) ON bandomi.idresidence = [dbo].residence.idresidence LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON bandomi.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  bandomi.idbandomi IS NOT NULL 
GO

