IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[dichiaraltre_segview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[dichiaraltre_segview]
GO

CREATE VIEW [dbo].[dichiaraltre_segview] AS SELECT  dichiar.aa, dichiar.ct AS dichiar_ct, dichiar.cu AS dichiar_cu, dichiar.date AS dichiar_date, dichiar.extension AS dichiar_extension, dichiar.iddichiar, dichiar.iddichiarkind AS dichiar_iddichiarkind, [dbo].registry.title AS registry_title, dichiar.idreg, dichiar.lt AS dichiar_lt, dichiar.lu AS dichiar_lu, dichiar.protanno AS dichiar_protanno, dichiar.protnumero AS dichiar_protnumero, dichiar_altre.ct AS dichiar_altre_ct, dichiar_altre.cu AS dichiar_altre_cu, dichiar_altre.iddichiar AS dichiar_altre_iddichiar, [dbo].dichiaraltrekind.title AS dichiaraltrekind_title, dichiar_altre.iddichiaraltrekind AS dichiar_altre_iddichiaraltrekind, dichiar_altre.idreg AS dichiar_altre_idreg, dichiar_altre.lt AS dichiar_altre_lt, dichiar_altre.lu AS dichiar_altre_lu FROM [dbo].dichiar WITH (NOLOCK)  INNER JOIN dichiar_altre WITH (NOLOCK) ON dichiar.iddichiar = dichiar_altre.iddichiar AND dichiar.idreg = dichiar_altre.idreg LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON dichiar.idreg = [dbo].registry.idreg LEFT OUTER JOIN [dbo].dichiaraltrekind WITH (NOLOCK) ON dichiar_altre.iddichiaraltrekind = [dbo].dichiaraltrekind.iddichiaraltrekind WHERE  dichiar.iddichiar IS NOT NULL  AND dichiar.iddichiarkind = 5 AND dichiar.idreg IS NOT NULL  AND dichiar_altre.iddichiar IS NOT NULL  AND dichiar_altre.idreg IS NOT NULL 
GO

