CREATE VIEW [dbo].[edificiodefaultview] AS SELECT  edificio.address AS edificio_address, edificio.cap AS edificio_cap, edificio.code AS edificio_code, edificio.ct AS edificio_ct, edificio.cu AS edificio_cu, [dbo].geo_city.title AS geo_city_title, edificio.idcity, edificio.idedificio, [dbo].geo_nation.title AS geo_nation_title, edificio.idnation, [dbo].sede.title AS sede_title, edificio.idsede, edificio.latitude AS edificio_latitude, edificio.location AS edificio_location, edificio.longitude AS edificio_longitude, edificio.lt AS edificio_lt, edificio.lu AS edificio_lu, edificio.title, isnull('Denominazione: ' + edificio.title + '; ','') as dropdown_title FROM [dbo].edificio WITH (NOLOCK)  LEFT OUTER JOIN [dbo].geo_city WITH (NOLOCK) ON edificio.idcity = [dbo].geo_city.idcity LEFT OUTER JOIN [dbo].geo_nation WITH (NOLOCK) ON edificio.idnation = [dbo].geo_nation.idnation LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON edificio.idsede = [dbo].sede.idsede WHERE  edificio.idedificio IS NOT NULL  AND edificio.idsede IS NOT NULL 
GO

