CREATE VIEW [dbo].[esonerotitolostudioview] AS SELECT  esonero.aa,CASE WHEN esonero.applunavolta = 'S' THEN 'Si' WHEN esonero.applunavolta = 'N' THEN 'No' END AS esonero_applunavolta, esonero.ct AS esonero_ct, esonero.cu AS esonero_cu, esonero.description AS esonero_description, [dbo].costoscontodef.title AS costoscontodef_title, esonero.idcostoscontodef, esonero.idesonero, [dbo].esoneroanskind.title AS esoneroanskind_title, [dbo].esoneroanskind.description AS esoneroanskind_description, esonero.idesoneroanskind AS esonero_idesoneroanskind, esonero.lt AS esonero_lt, esonero.lu AS esonero_lu,CASE WHEN esonero.retroattivo = 'S' THEN 'Si' WHEN esonero.retroattivo = 'N' THEN 'No' END AS esonero_retroattivo,CASE WHEN esonero.soloconisee = 'S' THEN 'Si' WHEN esonero.soloconisee = 'N' THEN 'No' END AS esonero_soloconisee, esonero.title,CASE WHEN esonero_titolostudio.conseguitoincorso = 'S' THEN 'Si' WHEN esonero_titolostudio.conseguitoincorso = 'N' THEN 'No' END AS esonero_titolostudio_conseguitoincorso, esonero_titolostudio.ct AS esonero_titolostudio_ct, esonero_titolostudio.cu AS esonero_titolostudio_cu, esonero_titolostudio.dataconstutticf AS esonero_titolostudio_dataconstutticf, esonero_titolostudio.datalaurea AS esonero_titolostudio_datalaurea, esonero_titolostudio.idesonero AS esonero_titolostudio_idesonero, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, esonero_titolostudio.idstruttura, esonero_titolostudio.lt AS esonero_titolostudio_lt, esonero_titolostudio.lu AS esonero_titolostudio_lu,CASE WHEN esonero_titolostudio.nellistituto = 'S' THEN 'Si' WHEN esonero_titolostudio.nellistituto = 'N' THEN 'No' END AS esonero_titolostudio_nellistituto,CASE WHEN esonero_titolostudio.noabbr = 'S' THEN 'Si' WHEN esonero_titolostudio.noabbr = 'N' THEN 'No' END AS esonero_titolostudio_noabbr,CASE WHEN esonero_titolostudio.noparttime = 'S' THEN 'Si' WHEN esonero_titolostudio.noparttime = 'N' THEN 'No' END AS esonero_titolostudio_noparttime, esonero_titolostudio.votomin AS esonero_titolostudio_votomin, isnull('Denominazione: ' + esonero.title + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].esonero WITH (NOLOCK)  INNER JOIN esonero_titolostudio WITH (NOLOCK) ON esonero.idesonero = esonero_titolostudio.idesonero LEFT OUTER JOIN [dbo].costoscontodef WITH (NOLOCK) ON esonero.idcostoscontodef = [dbo].costoscontodef.idcostoscontodef LEFT OUTER JOIN [dbo].esoneroanskind WITH (NOLOCK) ON esonero.idesoneroanskind = [dbo].esoneroanskind.idesoneroanskind LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON esonero_titolostudio.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  esonero.idesonero IS NOT NULL  AND esonero_titolostudio.idesonero IS NOT NULL 
GO

