CREATE VIEW [expensesegview] AS SELECT  expense.adate AS expense_adate, expense.autocode AS expense_autocode, expense.autokind AS expense_autokind, expense.cigcode AS expense_cigcode, expense.ct AS expense_ct, expense.cu AS expense_cu, expense.cupcode AS expense_cupcode, expense.description, expense.doc AS expense_doc, expense.docdate AS expense_docdate, expense.expiration AS expense_expiration, expense.external_reference AS expense_external_reference, clawback.description AS clawback_description, expense.idclawback, expense.idexp, expense.idformerexpense AS expense_idformerexpense, expense.idinc_linked AS expense_idinc_linked, expense.idpayment AS expense_idpayment, [dbo].registry.title AS registry_title, expense.idreg, expense.lt AS expense_lt, expense.lu AS expense_lu, expense.nmov AS expense_nmov, expense.nphase AS expense_nphase, expense.parentidexp AS expense_parentidexp, expense.rtf AS expense_rtf, expense.txt AS expense_txt, expense.ymov AS expense_ymov, isnull('Descrizione: ' + expense.description + '; ','') + ' ' + isnull('Esercizio : ' + CAST( expense.ymov AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Numero movimento : ' + CAST( expense.nmov AS NVARCHAR(64)) + '; ','') as dropdown_title FROM expense WITH (NOLOCK)  LEFT OUTER JOIN clawback WITH (NOLOCK) ON expense.idclawback = clawback.idclawback LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON expense.idreg = [dbo].registry.idreg WHERE  expense.idexp IS NOT NULL 
GO

