-- CREAZIONE VISTA fasciaiseedefmoreview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[fasciaiseedefmoreview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[fasciaiseedefmoreview]
GO

CREATE VIEW [dbo].[fasciaiseedefmoreview] AS SELECT  fasciaiseedef.ct AS fasciaiseedef_ct, fasciaiseedef.cu AS fasciaiseedef_cu, fasciaiseedef.idcostoscontodef, fasciaiseedef.idfasciaisee, fasciaiseedef.idfasciaiseedef, fasciaiseedef.lt AS fasciaiseedef_lt, fasciaiseedef.lu AS fasciaiseedef_lu, isnull('Fascia ISEE: ' + fasciaiseedef.idfasciaisee + '; ','') as dropdown_title FROM [dbo].fasciaiseedef WITH (NOLOCK)  WHERE  fasciaiseedef.idcostoscontodef IS NOT NULL  AND fasciaiseedef.idfasciaiseedef IS NOT NULL 
GO

