CREATE VIEW [getcostididatticadefaultview] AS SELECT  getcostididattica.aa, getcostididattica.aaprogrammata, getcostididattica.affidamento AS getcostididattica_affidamento, getcostididattica.corsostudio AS getcostididattica_corsostudio, getcostididattica.costo AS getcostididattica_costo, getcostididattica.costoorariodacontratto AS getcostididattica_costoorariodacontratto, getcostididattica.curriculum AS getcostididattica_curriculum, getcostididattica.docente AS getcostididattica_docente, getcostididattica.idaffidamento, [dbo].affidamentokind.title AS affidamentokind_title, getcostididattica.idaffidamentokind AS getcostididattica_idaffidamentokind, [dbo].contrattokind.title AS contrattokind_title, getcostididattica.idcontrattokind, [dbo].corsostudio.title AS corsostudio_title, [dbo].corsostudio.annoistituz AS corsostudio_annoistituz, getcostididattica.idcorsostudio, [dbo].didprog.title AS didprog_title, [dbo].annoaccademico.aa AS annoaccademico_aa, [dbo].sede.title AS sede_title, getcostididattica.iddidprog, [dbo].didprogcurr.title AS didprogcurr_title, getcostididattica.iddidprogcurr, [dbo].insegn.denominazione AS insegn_denominazione, [dbo].insegn.codice AS insegn_codice, getcostididattica.idinsegn, [dbo].insegninteg.denominazione AS insegninteg_denominazione, [dbo].insegninteg.codice AS insegninteg_codice, getcostididattica.idinsegninteg, registry_registry_docentidocenti.title AS registrydocenti_title, getcostididattica.idreg_docenti, sede_getcostididattica.title AS sede_getcostididattica_title, getcostididattica.idsede, getcostididattica.insegnamento AS getcostididattica_insegnamento, getcostididattica.modulo AS getcostididattica_modulo, getcostididattica.ruolo AS getcostididattica_ruolo, getcostididattica.sede AS getcostididattica_sede, isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Denominazione Sede: ' + [dbo].sede.title + '; ','') as dropdown_title FROM getcostididattica WITH (NOLOCK)  LEFT OUTER JOIN [dbo].affidamentokind WITH (NOLOCK) ON getcostididattica.idaffidamentokind = [dbo].affidamentokind.idaffidamentokind LEFT OUTER JOIN [dbo].contrattokind WITH (NOLOCK) ON getcostididattica.idcontrattokind = [dbo].contrattokind.idcontrattokind LEFT OUTER JOIN [dbo].corsostudio WITH (NOLOCK) ON getcostididattica.idcorsostudio = [dbo].corsostudio.idcorsostudio LEFT OUTER JOIN [dbo].didprog WITH (NOLOCK) ON getcostididattica.iddidprog = [dbo].didprog.iddidprog LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON didprog.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].didprogcurr WITH (NOLOCK) ON getcostididattica.iddidprogcurr = [dbo].didprogcurr.iddidprogcurr LEFT OUTER JOIN [dbo].insegn WITH (NOLOCK) ON getcostididattica.idinsegn = [dbo].insegn.idinsegn LEFT OUTER JOIN [dbo].insegninteg WITH (NOLOCK) ON getcostididattica.idinsegninteg = [dbo].insegninteg.idinsegninteg LEFT OUTER JOIN [dbo].registry_docenti AS registry_docentidocenti WITH (NOLOCK) ON getcostididattica.idreg_docenti = registry_docentidocenti.idreg LEFT OUTER JOIN [dbo].registry AS registry_registry_docentidocenti WITH (NOLOCK) ON registry_docentidocenti.idreg = registry_registry_docentidocenti.idreg LEFT OUTER JOIN [dbo].sede AS sede_getcostididattica WITH (NOLOCK) ON getcostididattica.idsede = sede_getcostididattica.idsede WHERE  getcostididattica.aa IS NOT NULL  AND getcostididattica.idaffidamento IS NOT NULL  AND getcostididattica.idcontrattokind IS NOT NULL  AND getcostididattica.idcorsostudio IS NOT NULL  AND getcostididattica.iddidprog IS NOT NULL  AND getcostididattica.iddidprogcurr IS NOT NULL  AND getcostididattica.idsede IS NOT NULL 
GO

