-- CREAZIONE VISTA insegndefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[insegndefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[insegndefaultview]
GO

CREATE VIEW [dbo].[insegndefaultview] AS SELECT  insegn.codice AS insegn_codice, insegn.ct AS insegn_ct, insegn.cu AS insegn_cu, insegn.denominazione, insegn.denominazione_en AS insegn_denominazione_en, [dbo].corsostudio.title AS corsostudio_title, [dbo].corsostudio.annoistituz AS corsostudio_annoistituz, insegn.idcorsostudio, [dbo].corsostudiokind.title AS corsostudiokind_title, insegn.idcorsostudiokind AS insegn_idcorsostudiokind, insegn.idinsegn, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, insegn.idstruttura, insegn.lt AS insegn_lt, insegn.lu AS insegn_lu, isnull('Denominazione: ' + insegn.denominazione + '; ','') + ' ' + isnull('; Codice  : ' + insegn.codice + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') as dropdown_title FROM [dbo].insegn WITH (NOLOCK)  LEFT OUTER JOIN [dbo].corsostudio WITH (NOLOCK) ON insegn.idcorsostudio = [dbo].corsostudio.idcorsostudio LEFT OUTER JOIN [dbo].corsostudiokind WITH (NOLOCK) ON insegn.idcorsostudiokind = [dbo].corsostudiokind.idcorsostudiokind LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON insegn.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  insegn.idinsegn IS NOT NULL 
GO

