-- CREAZIONE VISTA iscrizionebmisegview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[iscrizionebmisegview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[iscrizionebmisegview]
GO

CREATE VIEW [dbo].[iscrizionebmisegview] AS SELECT  iscrizionebmi.ct AS iscrizionebmi_ct, iscrizionebmi.cu AS iscrizionebmi_cu, iscrizionebmi.data AS iscrizionebmi_data, iscrizionebmi.idbandomi, [dbo].iscrizione.anno AS iscrizione_anno, [dbo].iscrizione.iddidprog AS iscrizione_iddidprog, [dbo].annoaccademico.aa AS annoaccademico_aa, iscrizionebmi.idiscrizione, iscrizionebmi.idiscrizionebmi, [dbo].registry.title AS registry_title, iscrizionebmi.idreg, iscrizionebmi.lt AS iscrizionebmi_lt, iscrizionebmi.lu AS iscrizionebmi_lu,(select top 1 idcefr_compasc 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_compasc,
						(select top 1 idcefr_complett 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_complett,
						(select top 1 idcefr_parlinter 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_parlinter,
						(select top 1 idcefr_parlprod 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_parlprod,
						(select top 1 idcefr_scritto 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_scritto,
						(select top 1 idnation 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idiscrizionebmi = iscrizionebmi.idiscrizionebmi
						 order by cefrlanglevel.idnation desc) as idnation, isnull('Identificativo: ' + [dbo].registry.title + '; ','') + ' ' + isnull('del ' + CONVERT(VARCHAR, iscrizionebmi.data, 103),'') + ' ' + isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Iscrizione: ' + CAST( [dbo].iscrizione.anno AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Iscrizione: ' + CAST( [dbo].iscrizione.iddidprog AS NVARCHAR(64)) + '; ','') as dropdown_title FROM [dbo].iscrizionebmi WITH (NOLOCK)  LEFT OUTER JOIN [dbo].iscrizione WITH (NOLOCK) ON iscrizionebmi.idiscrizione = [dbo].iscrizione.idiscrizione LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON iscrizione.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON iscrizionebmi.idreg = [dbo].registry.idreg WHERE  iscrizionebmi.idbandomi IS NOT NULL  AND iscrizionebmi.idiscrizionebmi IS NOT NULL  AND iscrizionebmi.idreg IS NOT NULL 
GO

