-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA istanzaimm_segpreview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[istanzaimm_segpreview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[istanzaimm_segpreview]
GO

CREATE VIEW [dbo].[istanzaimm_segpreview] AS SELECT  istanza.aa, istanza.ct AS istanza_ct, istanza.cu AS istanza_cu, istanza.data AS istanza_data, istanza.extension AS istanza_extension, istanza.idcorsostudio, [dbo].didprog.title AS didprog_title, [dbo].annoaccademico.aa AS annoaccademico_aa, [dbo].sede.title AS sede_title, istanza.iddidprog, istanza.idiscrizione AS istanza_idiscrizione, istanza.idistanza, istanza.idistanzakind, registry_registry_studentistudenti.idtitle AS registrystudenti_idtitle, registry_registry_studentistudenti.title AS registrystudenti_title, registry_registry_studentistudenti.surname AS registrystudenti_surname, registry_registry_studentistudenti.forename AS registrystudenti_forename, registry_registry_studentistudenti.cf AS registrystudenti_cf, istanza.idreg_studenti, [dbo].statuskind.title AS statuskind_title, istanza.idstatuskind AS istanza_idstatuskind, istanza.lt AS istanza_lt, istanza.lu AS istanza_lu, istanza.paridistanza AS istanza_paridistanza, istanza.protanno AS istanza_protanno, istanza.protnumero AS istanza_protnumero, istanza_imm.ct AS istanza_imm_ct, istanza_imm.cu AS istanza_imm_cu, istanza_imm.idcorsostudio AS istanza_imm_idcorsostudio, istanza_imm.iddidprog AS istanza_imm_iddidprog, [dbo].didprogcurr.title AS didprogcurr_title, istanza_imm.iddidprogcurr AS istanza_imm_iddidprogcurr, [dbo].didprogori.title AS didprogori_title, istanza_imm.iddidprogori AS istanza_imm_iddidprogori, istanza_imm.idistanza AS istanza_imm_idistanza, istanza_imm.idistanzakind AS istanza_imm_idistanzakind, istanza_imm.idreg AS istanza_imm_idreg, istanza_imm.lt AS istanza_imm_lt, istanza_imm.lu AS istanza_imm_lu, istanza_imm.motivrit AS istanza_imm_motivrit,CASE WHEN istanza_imm.parttime = 'S' THEN 'Si' WHEN istanza_imm.parttime = 'N' THEN 'No' END AS istanza_imm_parttime,CASE WHEN istanza_imm.pre = 'S' THEN 'Si' WHEN istanza_imm.pre = 'N' THEN 'No' END AS istanza_imm_pre, isnull('Studente: ' + registry_registry_studentistudenti.idtitle + '; ','') + ' ' + isnull('Studente: ' + registry_registry_studentistudenti.title + '; ','') + ' ' + isnull('Studente: ' + registry_registry_studentistudenti.surname + '; ','') + ' ' + isnull('Studente: ' + registry_registry_studentistudenti.forename + '; ','') + ' ' + isnull('Studente: ' + registry_registry_studentistudenti.cf + '; ','') + ' ' + isnull('del ' + CONVERT(VARCHAR, istanza.data, 103),'') + ' ' + isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Denominazione Sede: ' + [dbo].sede.title + '; ','') + ' ' + isnull('Status: ' + [dbo].statuskind.title + '; ','') as dropdown_title FROM [dbo].istanza WITH (NOLOCK)  INNER JOIN istanza_imm WITH (NOLOCK) ON istanza.idistanza = istanza_imm.idistanza AND istanza.idistanzakind = istanza_imm.idistanzakind AND istanza.idreg_studenti = istanza_imm.idreg LEFT OUTER JOIN [dbo].didprog WITH (NOLOCK) ON istanza.iddidprog = [dbo].didprog.iddidprog LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON didprog.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].registry_studenti AS registry_studentistudenti WITH (NOLOCK) ON istanza.idreg_studenti = registry_studentistudenti.idreg LEFT OUTER JOIN [dbo].registry AS registry_registry_studentistudenti WITH (NOLOCK) ON registry_studentistudenti.idreg = registry_registry_studentistudenti.idreg LEFT OUTER JOIN [dbo].statuskind WITH (NOLOCK) ON istanza.idstatuskind = [dbo].statuskind.idstatuskind LEFT OUTER JOIN [dbo].didprogcurr WITH (NOLOCK) ON istanza_imm.iddidprogcurr = [dbo].didprogcurr.iddidprogcurr LEFT OUTER JOIN [dbo].didprogori WITH (NOLOCK) ON istanza_imm.iddidprogori = [dbo].didprogori.iddidprogori WHERE  istanza.idcorsostudio IS NOT NULL  AND istanza.iddidprog IS NOT NULL  AND istanza.idistanza IS NOT NULL  AND istanza.idistanzakind IS NOT NULL  AND istanza.idreg_studenti IS NOT NULL  AND istanza.idstatuskind in (select idstatuskind from statuskind where istanze = 'S') AND istanza_imm.idcorsostudio IS NOT NULL  AND istanza_imm.iddidprog IS NOT NULL  AND istanza_imm.idistanza IS NOT NULL  AND istanza_imm.idistanzakind IS NOT NULL  AND istanza_imm.idreg IS NOT NULL 
GO

