tanzakind AND istanza.idreg_studenti = istanza_pas.idreg LEFT OUTER JOIN statuskind WITH (NOLOCK) ON istanza.idstatuskind = statuskind.idstatuskind LEFT OUTER JOIN iscrizione AS iscrizionefrom WITH (NOLOCK) ON istanza_pas.idiscrizione_from = iscrizionefrom.idiscrizione WHERE  istanza.idcorsostudio IS NOT NULL  AND istanza.iddidprog IS NOT NULL  AND istanza.idiscrizione IS NOT NULL  AND istanza.idistanza IS NOT NULL  AND istanza.idistanzakind IS NOT NULL  AND istanza.idreg_studenti IS NOT NULL  AND istanza_pas.idcorsostudio IS NOT NULL  AND istanza_pas.iddidprog IS NOT NULL  AND istanza_pas.idiscrizione IS NOT NULL  AND istanza_pas.idistanza IS NOT NULL  AND istanza_pas.idistanzakind IS NOT NULL  AND istanza_pas.idreg IS NOT NULL 



