-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA istanzatru_segview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[istanzatru_segview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[istanzatru_segview]
GO

CREATE VIEW [dbo].[istanzatru_segview] AS SELECT  istanza.aa, istanza.ct AS istanza_ct, istanza.cu AS istanza_cu, istanza.data AS istanza_data, istanza.extension AS istanza_extension, [dbo].corsostudio.title AS corsostudio_title, [dbo].corsostudio.annoistituz AS corsostudio_annoistituz, istanza.idcorsostudio, [dbo].didprog.title AS didprog_title, [dbo].annoaccademico.aa AS annoaccademico_aa, [dbo].sede.title AS sede_title, istanza.iddidprog, [dbo].iscrizione.anno AS iscrizione_anno, [dbo].iscrizione.iddidprog AS iscrizione_iddidprog, annoaccademico_iscrizione.aa AS annoaccademico_iscrizione_aa, istanza.idiscrizione, istanza.idistanza, istanza.idistanzakind, registry_registry_studentistudenti.title AS registrystudenti_title, istanza.idreg_studenti, [dbo].statuskind.title AS statuskind_title, istanza.idstatuskind AS istanza_idstatuskind, istanza.lt AS istanza_lt, istanza.lu AS istanza_lu, istanzaparent.idistanzakind AS istanzaparent_idistanzakind, istanzaparent.idreg_studenti AS istanzaparent_idreg_studenti, annoaccademico_istanza.aa AS annoaccademico_istanza_aa, istanzaparent.data AS istanzaparent_data, didprog_istanza.title AS didprog_istanza_title, didprog_istanza.aa AS didprog_istanza_aa, didprog_istanza.idsede AS didprog_istanza_idsede, statuskind_istanza.title AS statuskind_istanza_title, iscrizione_istanza.anno AS iscrizione_istanza_anno, iscrizione_istanza.iddidprog AS iscrizione_istanza_iddidprog, iscrizione_istanza.aa AS iscrizione_istanza_aa, istanza.paridistanza, istanza.protanno AS istanza_protanno, istanza.protnumero AS istanza_protnumero, istanza_tru.ct AS istanza_tru_ct, istanza_tru.cu AS istanza_tru_cu, istanza_tru.idistanza AS istanza_tru_idistanza, istanza_tru.idistanzakind AS istanza_tru_idistanzakind, istanza_tru.idreg AS istanza_tru_idreg, istanza_tru.idreg_istituti AS istanza_tru_idreg_istituti, istanza_tru.lt AS istanza_tru_lt, istanza_tru.lu AS istanza_tru_lu, isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_istanza.aa + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_iscrizione.aa + '; ','') + ' ' + isnull('Denominazione Sede: ' + [dbo].sede.title + '; ','') + ' ' + isnull('Denominazione Didattica programmata: ' + didprog_istanza.title + '; ','') + ' ' + isnull('Stato Status: ' + statuskind_istanza.title + '; ','') + ' ' + isnull('Anno accademico Didattica programmata: ' + didprog_istanza.aa + '; ','') + ' ' + isnull('Sede Didattica programmata: ' + CAST( didprog_istanza.idsede AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Anno di corso Iscrizione: ' + CAST( iscrizione_istanza.anno AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Didattica programmata Iscrizione: ' + CAST( iscrizione_istanza.iddidprog AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Anno accademico Iscrizione: ' + iscrizione_istanza.aa + '; ','') as dropdown_title FROM [dbo].istanza WITH (NOLOCK)  INNER JOIN istanza_tru WITH (NOLOCK) ON istanza.idistanza = istanza_tru.idistanza AND istanza.idistanzakind = istanza_tru.idistanzakind AND istanza.idreg_studenti = istanza_tru.idreg LEFT OUTER JOIN [dbo].corsostudio WITH (NOLOCK) ON istanza.idcorsostudio = [dbo].corsostudio.idcorsostudio LEFT OUTER JOIN [dbo].didprog WITH (NOLOCK) ON istanza.iddidprog = [dbo].didprog.iddidprog LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON didprog.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].iscrizione WITH (NOLOCK) ON istanza.idiscrizione = [dbo].iscrizione.idiscrizione LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_iscrizione WITH (NOLOCK) ON iscrizione.aa = annoaccademico_iscrizione.aa LEFT OUTER JOIN [dbo].registry_studenti AS registry_studentistudenti WITH (NOLOCK) ON istanza.idreg_studenti = registry_studentistudenti.idreg LEFT OUTER JOIN [dbo].registry AS registry_registry_studentistudenti WITH (NOLOCK) ON registry_studentistudenti.idreg = registry_registry_studentistudenti.idreg LEFT OUTER JOIN [dbo].statuskind WITH (NOLOCK) ON istanza.idstatuskind = [dbo].statuskind.idstatuskind LEFT OUTER JOIN [dbo].istanza AS istanzaparent WITH (NOLOCK) ON istanza.paridistanza = istanzaparent.idistanza LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_istanza WITH (NOLOCK) ON istanza.aa = annoaccademico_istanza.aa LEFT OUTER JOIN [dbo].didprog AS didprog_istanza WITH (NOLOCK) ON istanza.iddidprog = didprog_istanza.iddidprog LEFT OUTER JOIN [dbo].statuskind AS statuskind_istanza WITH (NOLOCK) ON istanza.idstatuskind = statuskind_istanza.idstatuskind LEFT OUTER JOIN [dbo].iscrizione AS iscrizione_istanza WITH (NOLOCK) ON istanza.idiscrizione = iscrizione_istanza.idiscrizione WHERE  istanza.idistanza IS NOT NULL  AND istanza.idistanzakind = 8 AND istanza.idistanzakind IS NOT NULL  AND istanza.idreg_studenti IS NOT NULL  AND istanza.idstatuskind in (select idstatuskind from statuskind where istanze = 'S') AND istanza_tru.idistanza IS NOT NULL  AND istanza_tru.idistanzakind IS NOT NULL  AND istanza_tru.idreg IS NOT NULL 
GO

