-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA learningagrstudsegview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[learningagrstudsegview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[learningagrstudsegview]
GO

CREATE VIEW [dbo].[learningagrstudsegview] AS SELECT  learningagrstud.ct AS learningagrstud_ct, learningagrstud.cu AS learningagrstud_cu, learningagrstud.idbandomi, learningagrstud.idiscrizionebmi, [dbo].learningagrkind.title AS learningagrkind_title, [dbo].learningagrkind.description AS learningagrkind_description, learningagrstud.idlearningagrkind AS learningagrstud_idlearningagrkind, learningagrstud.idlearningagrstud, learningagrstud.idreg, registry_registry_istitutiesteriistitutiesteri.title AS registryistitutiesteri_title, learningagrstud.idreg_istitutiesteri, learningagrstud.lt AS learningagrstud_lt, learningagrstud.lu AS learningagrstud_lu, learningagrstud.note AS learningagrstud_note, learningagrstud.start AS learningagrstud_start, learningagrstud.stop AS learningagrstud_stop,(select top 1 idcefr_compasc 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_compasc,
						(select top 1 idcefr_complett 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_complett,
						(select top 1 idcefr_parlinter 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_parlinter,
						(select top 1 idcefr_parlprod 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_parlprod,
						(select top 1 idcefr_scritto 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as cefrlanglevel_idcefr_scritto,
						(select top 1 idnation 
						from dbo.cefrlanglevel 
						where dbo.cefrlanglevel.idlearningagrstud = learningagrstud.idlearningagrstud
						 order by cefrlanglevel.idnation desc) as idnation FROM [dbo].learningagrstud WITH (NOLOCK)  LEFT OUTER JOIN [dbo].learningagrkind WITH (NOLOCK) ON learningagrstud.idlearningagrkind = [dbo].learningagrkind.idlearningagrkind LEFT OUTER JOIN [dbo].registry_istitutiesteri AS registry_istitutiesteriistitutiesteri WITH (NOLOCK) ON learningagrstud.idreg_istitutiesteri = registry_istitutiesteriistitutiesteri.idreg LEFT OUTER JOIN [dbo].registry AS registry_registry_istitutiesteriistitutiesteri WITH (NOLOCK) ON registry_istitutiesteriistitutiesteri.idreg = registry_registry_istitutiesteriistitutiesteri.idreg WHERE  learningagrstud.idbandomi IS NOT NULL  AND learningagrstud.idiscrizionebmi IS NOT NULL  AND learningagrstud.idlearningagrstud IS NOT NULL  AND learningagrstud.idreg IS NOT NULL 
GO

