-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA nullaostaimm_seganagstuview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[nullaostaimm_seganagstuview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[nullaostaimm_seganagstuview]
GO

CREATE VIEW [dbo].[nullaostaimm_seganagstuview] AS SELECT  nullaosta.ct AS nullaosta_ct, nullaosta.cu AS nullaosta_cu, nullaosta.data, nullaosta.extension AS nullaosta_extension, nullaosta.idcorsostudio, nullaosta.iddidprog, nullaosta.idiscrizione AS nullaosta_idiscrizione, nullaosta.idistanza, nullaosta.idistanzakind, nullaosta.idnullaosta, nullaosta.idreg, nullaosta.lt AS nullaosta_lt, nullaosta.lu AS nullaosta_lu, nullaosta.protanno AS nullaosta_protanno, nullaosta.protnumero AS nullaosta_protnumero, nullaosta_imm.annoimm AS nullaosta_imm_annoimm, nullaosta_imm.ct AS nullaosta_imm_ct, nullaosta_imm.cu AS nullaosta_imm_cu, nullaosta_imm.idcorsostudio AS nullaosta_imm_idcorsostudio, nullaosta_imm.iddidprog AS nullaosta_imm_iddidprog, [dbo].didprogcurr.title AS didprogcurr_title, nullaosta_imm.iddidprogcurr AS nullaosta_imm_iddidprogcurr, [dbo].didprogori.title AS didprogori_title, nullaosta_imm.iddidprogori AS nullaosta_imm_iddidprogori, nullaosta_imm.idistanza AS nullaosta_imm_idistanza, nullaosta_imm.idistanzakind AS nullaosta_imm_idistanzakind, nullaosta_imm.idnullaosta AS nullaosta_imm_idnullaosta, nullaosta_imm.idreg AS nullaosta_imm_idreg, nullaosta_imm.lt AS nullaosta_imm_lt, nullaosta_imm.lu AS nullaosta_imm_lu,CASE WHEN nullaosta_imm.parttime = 'S' THEN 'Si' WHEN nullaosta_imm.parttime = 'N' THEN 'No' END AS nullaosta_imm_parttime, isnull('del ' + CONVERT(VARCHAR, nullaosta.data, 103),'') + ' ' + isnull('all''anno di corso : ' + CAST( nullaosta_imm.annoimm AS NVARCHAR(64)) + '; ','') as dropdown_title FROM [dbo].nullaosta WITH (NOLOCK)  INNER JOIN nullaosta_imm WITH (NOLOCK) ON nullaosta.idcorsostudio = nullaosta_imm.idcorsostudio AND nullaosta.iddidprog = nullaosta_imm.iddidprog AND nullaosta.idistanza = nullaosta_imm.idistanza AND nullaosta.idistanzakind = nullaosta_imm.idistanzakind AND nullaosta.idnullaosta = nullaosta_imm.idnullaosta AND nullaosta.idreg = nullaosta_imm.idreg LEFT OUTER JOIN [dbo].didprogcurr WITH (NOLOCK) ON nullaosta_imm.iddidprogcurr = [dbo].didprogcurr.iddidprogcurr LEFT OUTER JOIN [dbo].didprogori WITH (NOLOCK) ON nullaosta_imm.iddidprogori = [dbo].didprogori.iddidprogori WHERE  nullaosta.idcorsostudio IS NOT NULL  AND nullaosta.iddidprog IS NOT NULL  AND nullaosta.idistanza IS NOT NULL  AND nullaosta.idistanzakind IS NOT NULL  AND nullaosta.idnullaosta IS NOT NULL  AND nullaosta.idreg IS NOT NULL  AND nullaosta_imm.idcorsostudio IS NOT NULL  AND nullaosta_imm.iddidprog IS NOT NULL  AND nullaosta_imm.idistanza IS NOT NULL  AND nullaosta_imm.idistanzakind IS NOT NULL  AND nullaosta_imm.idnullaosta IS NOT NULL  AND nullaosta_imm.idreg IS NOT NULL 
GO

