-- FINE GENERAZIONE SCRIPT --

--[DBO]--
-- CREAZIONE VISTA praticasegstudview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[praticasegstudview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[praticasegstudview]
GO

CREATE VIEW [dbo].[praticasegstudview] AS SELECT  pratica.ct AS pratica_ct, pratica.cu AS pratica_cu, [dbo].corsostudio.title AS corsostudio_title, [dbo].corsostudio.annoistituz AS corsostudio_annoistituz, pratica.idcorsostudio, [dbo].dichiarkind.title AS dichiarkind_title, [dbo].dichiar.idreg AS dichiar_idreg, [dbo].annoaccademico.aa AS annoaccademico_aa, [dbo].dichiar.date AS dichiar_date, pratica.iddichiar, [dbo].didprog.title AS didprog_title, annoaccademico_didprog.aa AS annoaccademico_didprog_aa, [dbo].sede.title AS sede_title, pratica.iddidprog, [dbo].iscrizione.anno AS iscrizione_anno, [dbo].iscrizione.iddidprog AS iscrizione_iddidprog, annoaccademico_iscrizione.aa AS annoaccademico_iscrizione_aa, pratica.idiscrizione, iscrizione_pratica.anno AS iscrizione_pratica_anno, iscrizione_pratica.iddidprog AS iscrizione_pratica_iddidprog, annoaccademico_iscrizione_1.aa AS annoaccademico_iscrizione_1_aa, pratica.idiscrizione_from AS pratica_idiscrizione_from, [dbo].istanza.idistanzakind AS istanza_idistanzakind, [dbo].istanza.idreg_studenti AS istanza_idreg_studenti, annoaccademico_istanza.aa AS annoaccademico_istanza_aa, [dbo].istanza.data AS istanza_data, didprog_istanza.title AS didprog_istanza_title, didprog_istanza.aa AS didprog_istanza_aa, didprog_istanza.idsede AS didprog_istanza_idsede, [dbo].statuskind.title AS statuskind_title, iscrizione_istanza.anno AS iscrizione_istanza_anno, iscrizione_istanza.iddidprog AS iscrizione_istanza_iddidprog, iscrizione_istanza.aa AS iscrizione_istanza_aa, pratica.idistanza, [dbo].istanzakind.title AS istanzakind_title, pratica.idistanzakind, pratica.idpratica, [dbo].registry.title AS registry_title, pratica.idreg, statuskind_pratica.title AS statuskind_pratica_title, pratica.idstatuskind AS pratica_idstatuskind, [dbo].istattitolistudio.titolo AS istattitolistudio_titolo, [dbo].titolostudio.voto AS titolostudio_voto, [dbo].titolostudio.votosu AS titolostudio_votosu, [dbo].titolostudio.votolode AS titolostudio_votolode, annoaccademico_titolostudio.aa AS annoaccademico_titolostudio_aa, pratica.idtitolostudio AS pratica_idtitolostudio, pratica.lt AS pratica_lt, pratica.lu AS pratica_lu, pratica.protanno AS pratica_protanno, pratica.protnumero AS pratica_protnumero, isnull('Tipologia Tipologia: ' + [dbo].dichiarkind.title + '; ','') + ' ' + isnull('Studente: ' + [dbo].registry.title + '; ','') + ' ' + isnull('Titolo di studio Titolo ISTAT: ' + [dbo].istattitolistudio.titolo + '; ','') + ' ' + isnull('Codice Anno Accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_didprog.aa + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_istanza.aa + '; ','') + ' ' + isnull('Didattica programmata: ' + [dbo].didprog.title + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_iscrizione.aa + '; ','') + ' ' + isnull('Codice Anno accademico: ' + annoaccademico_iscrizione_1.aa + '; ','') + ' ' + isnull('Denominazione Sede: ' + [dbo].sede.title + '; ','') + ' ' + isnull('Denominazione Didattica programmata: ' + didprog_istanza.title + '; ','') + ' ' + isnull('Stato Status: ' + [dbo].statuskind.title + '; ','') + ' ' + isnull('Anno accademico Didattica programmata: ' + didprog_istanza.aa + '; ','') + ' ' + isnull('Sede Didattica programmata: ' + CAST( didprog_istanza.idsede AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Anno di corso Iscrizione: ' + CAST( iscrizione_istanza.anno AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Didattica programmata Iscrizione: ' + CAST( iscrizione_istanza.iddidprog AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Anno accademico Iscrizione: ' + iscrizione_istanza.aa + '; ','') + ' ' + isnull('Codice Anno accademco: ' + annoaccademico_titolostudio.aa + '; ','') as dropdown_title FROM [dbo].pratica WITH (NOLOCK)  LEFT OUTER JOIN [dbo].corsostudio WITH (NOLOCK) ON pratica.idcorsostudio = [dbo].corsostudio.idcorsostudio LEFT OUTER JOIN [dbo].dichiar WITH (NOLOCK) ON pratica.iddichiar = [dbo].dichiar.iddichiar LEFT OUTER JOIN [dbo].dichiarkind WITH (NOLOCK) ON dichiar.iddichiarkind = [dbo].dichiarkind.iddichiarkind LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON dichiar.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].didprog WITH (NOLOCK) ON pratica.iddidprog = [dbo].didprog.iddidprog LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_didprog WITH (NOLOCK) ON didprog.aa = annoaccademico_didprog.aa LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON didprog.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].iscrizione WITH (NOLOCK) ON pratica.idiscrizione = [dbo].iscrizione.idiscrizione LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_iscrizione WITH (NOLOCK) ON iscrizione.aa = annoaccademico_iscrizione.aa LEFT OUTER JOIN [dbo].iscrizione AS iscrizione_pratica WITH (NOLOCK) ON pratica.idiscrizione_from = iscrizione_pratica.idiscrizione LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_iscrizione_1 WITH (NOLOCK) ON iscrizione.aa = annoaccademico_iscrizione_1.aa LEFT OUTER JOIN [dbo].istanza WITH (NOLOCK) ON pratica.idistanza = [dbo].istanza.idistanza LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_istanza WITH (NOLOCK) ON istanza.aa = annoaccademico_istanza.aa LEFT OUTER JOIN [dbo].didprog AS didprog_istanza WITH (NOLOCK) ON istanza.iddidprog = didprog_istanza.iddidprog LEFT OUTER JOIN [dbo].statuskind WITH (NOLOCK) ON istanza.idstatuskind = [dbo].statuskind.idstatuskind LEFT OUTER JOIN [dbo].iscrizione AS iscrizione_istanza WITH (NOLOCK) ON istanza.idiscrizione = iscrizione_istanza.idiscrizione LEFT OUTER JOIN [dbo].istanzakind WITH (NOLOCK) ON pratica.idistanzakind = [dbo].istanzakind.idistanzakind LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON pratica.idreg = [dbo].registry.idreg LEFT OUTER JOIN [dbo].statuskind AS statuskind_pratica WITH (NOLOCK) ON pratica.idstatuskind = statuskind_pratica.idstatuskind LEFT OUTER JOIN [dbo].titolostudio WITH (NOLOCK) ON pratica.idtitolostudio = [dbo].titolostudio.idtitolostudio LEFT OUTER JOIN [dbo].istattitolistudio WITH (NOLOCK) ON titolostudio.idistattitolistudio = [dbo].istattitolistudio.idistattitolistudio LEFT OUTER JOIN [dbo].annoaccademico AS annoaccademico_titolostudio WITH (NOLOCK) ON titolostudio.aa = annoaccademico_titolostudio.aa WHERE  pratica.idcorsostudio IS NOT NULL  AND pratica.iddidprog IS NOT NULL  AND pratica.idiscrizione IS NOT NULL  AND pratica.idistanza IS NOT NULL  AND pratica.idistanzakind IS NOT NULL  AND pratica.idpratica IS NOT NULL  AND pratica.idreg IS NOT NULL 
GO

