-- CREAZIONE VISTA provadefaultview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[provadefaultview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[provadefaultview]
GO

CREATE VIEW [dbo].[provadefaultview] AS SELECT  prova.ct AS prova_ct, prova.cu AS prova_cu, prova.idappello, prova.idattivform AS prova_idattivform, prova.idcorsostudio AS prova_idcorsostudio, prova.iddidprog AS prova_iddidprog, prova.idprova, [dbo].questionario.title AS questionario_title, prova.idquestionario, [dbo].valutazionekind.title AS valutazionekind_title, prova.idvalutazionekind AS prova_idvalutazionekind, prova.lt AS prova_lt, prova.lu AS prova_lu, prova.programma AS prova_programma, prova.start AS prova_start, prova.stop AS prova_stop, prova.title,(select top 1 idreg_docenti 
						from dbo.commiss 
						where dbo.commiss.idprova = prova.idprova
						 order by commiss.idcommiss asc ) as idreg_docenti, isnull('Denominazione: ' + prova.title + '; ','') + ' ' + isnull('dal ' + CONVERT(VARCHAR, prova.start, 103),'') as dropdown_title FROM [dbo].prova WITH (NOLOCK)  LEFT OUTER JOIN [dbo].questionario WITH (NOLOCK) ON prova.idquestionario = [dbo].questionario.idquestionario LEFT OUTER JOIN [dbo].valutazionekind WITH (NOLOCK) ON prova.idvalutazionekind = [dbo].valutazionekind.idvalutazionekind WHERE  prova.idappello IS NOT NULL  AND prova.idprova IS NOT NULL 
GO

