CREATE VIEW [dbo].[registryaddressuserview] AS SELECT CASE WHEN registryaddress.active = 'S' THEN 'Si' WHEN registryaddress.active = 'N' THEN 'No' END AS registryaddress_active, registryaddress.address, registryaddress.annotations AS registryaddress_annotations, registryaddress.cap AS registryaddress_cap, registryaddress.ct AS registryaddress_ct, registryaddress.cu AS registryaddress_cu,CASE WHEN registryaddress.flagforeign = 'S' THEN 'Si' WHEN registryaddress.flagforeign = 'N' THEN 'No' END AS registryaddress_flagforeign, [dbo].address.description AS address_description, registryaddress.idaddresskind, [dbo].geo_city.title AS geo_city_title, registryaddress.idcity, registryaddress.idnation AS registryaddress_idnation, registryaddress.idreg, registryaddress.location AS registryaddress_location, registryaddress.lt AS registryaddress_lt, registryaddress.lu AS registryaddress_lu, registryaddress.officename AS registryaddress_officename, registryaddress.recipientagency AS registryaddress_recipientagency, registryaddress.start, registryaddress.stop AS registryaddress_stop, isnull('Indirizzo: ' + registryaddress.address + '; ','') + ' ' + isnull('CAP: ' + registryaddress.cap + '; ','') + ' ' + isnull('Comune: ' + [dbo].geo_city.title + '; ','') as dropdown_title FROM [dbo].registryaddress WITH (NOLOCK)  LEFT OUTER JOIN [dbo].address WITH (NOLOCK) ON registryaddress.idaddresskind = [dbo].address.idaddress LEFT OUTER JOIN [dbo].geo_city WITH (NOLOCK) ON registryaddress.idcity = [dbo].geo_city.idcity WHERE  registryaddress.idaddresskind IS NOT NULL  AND registryaddress.idreg IS NOT NULL  AND registryaddress.start IS NOT NULL 
GO

