CREATE VIEW [dbo].[registryclasspersoneview] AS SELECT CASE WHEN registryclass.active = 'S' THEN 'Si' WHEN registryclass.active = 'N' THEN 'No' END AS registryclass_active, registryclass.ct AS registryclass_ct, registryclass.cu AS registryclass_cu, registryclass.description,CASE WHEN registryclass.flagbadgecode = 'S' THEN 'Si' WHEN registryclass.flagbadgecode = 'N' THEN 'No' END AS registryclass_flagbadgecode,CASE WHEN registryclass.flagbadgecode_forced = 'S' THEN 'Si' WHEN registryclass.flagbadgecode_forced = 'N' THEN 'No' END AS registryclass_flagbadgecode_forced,CASE WHEN registryclass.flagCF = 'S' THEN 'Si' WHEN registryclass.flagCF = 'N' THEN 'No' END AS registryclass_flagCF,CASE WHEN registryclass.flagcf_forced = 'S' THEN 'Si' WHEN registryclass.flagcf_forced = 'N' THEN 'No' END AS registryclass_flagcf_forced,CASE WHEN registryclass.flagcfbutton = 'S' THEN 'Si' WHEN registryclass.flagcfbutton = 'N' THEN 'No' END AS registryclass_flagcfbutton,CASE WHEN registryclass.flagextmatricula = 'S' THEN 'Si' WHEN registryclass.flagextmatricula = 'N' THEN 'No' END AS registryclass_flagextmatricula,CASE WHEN registryclass.flagextmatricula_forced = 'S' THEN 'Si' WHEN registryclass.flagextmatricula_forced = 'N' THEN 'No' END AS registryclass_flagextmatricula_forced,CASE WHEN registryclass.flagfiscalresidence = 'S' THEN 'Si' WHEN registryclass.flagfiscalresidence = 'N' THEN 'No' END AS registryclass_flagfiscalresidence,CASE WHEN registryclass.flagfiscalresidence_forced = 'S' THEN 'Si' WHEN registryclass.flagfiscalresidence_forced = 'N' THEN 'No' END AS registryclass_flagfiscalresidence_forced,CASE WHEN registryclass.flagforeigncf = 'S' THEN 'Si' WHEN registryclass.flagforeigncf = 'N' THEN 'No' END AS registryclass_flagforeigncf,CASE WHEN registryclass.flagforeigncf_forced = 'S' THEN 'Si' WHEN registryclass.flagforeigncf_forced = 'N' THEN 'No' END AS registryclass_flagforeigncf_forced,CASE WHEN registryclass.flaghuman = 'S' THEN 'Si' WHEN registryclass.flaghuman = 'N' THEN 'No' END AS registryclass_flaghuman,CASE WHEN registryclass.flaginfofromcfbutton = 'S' THEN 'Si' WHEN registryclass.flaginfofromcfbutton = 'N' THEN 'No' END AS registryclass_flaginfofromcfbutton,CASE WHEN registryclass.flagmaritalstatus = 'S' THEN 'Si' WHEN registryclass.flagmaritalstatus = 'N' THEN 'No' END AS registryclass_flagmaritalstatus,CASE WHEN registryclass.flagmaritalstatus_forced = 'S' THEN 'Si' WHEN registryclass.flagmaritalstatus_forced = 'N' THEN 'No' END AS registryclass_flagmaritalstatus_forced,CASE WHEN registryclass.flagmaritalsurname = 'S' THEN 'Si' WHEN registryclass.flagmaritalsurname = 'N' THEN 'No' END AS registryclass_flagmaritalsurname,CASE WHEN registryclass.flagmaritalsurname_forced = 'S' THEN 'Si' WHEN registryclass.flagmaritalsurname_forced = 'N' THEN 'No' END AS registryclass_flagmaritalsurname_forced,CASE WHEN registryclass.flagothers = 'S' THEN 'Si' WHEN registryclass.flagothers = 'N' THEN 'No' END AS registryclass_flagothers,CASE WHEN registryclass.flagothers_forced = 'S' THEN 'Si' WHEN registryclass.flagothers_forced = 'N' THEN 'No' END AS registryclass_flagothers_forced,CASE WHEN registryclass.flagp_iva = 'S' THEN 'Si' WHEN registryclass.flagp_iva = 'N' THEN 'No' END AS registryclass_flagp_iva,CASE WHEN registryclass.flagp_iva_forced = 'S' THEN 'Si' WHEN registryclass.flagp_iva_forced = 'N' THEN 'No' END AS registryclass_flagp_iva_forced,CASE WHEN registryclass.flagqualification = 'S' THEN 'Si' WHEN registryclass.flagqualification = 'N' THEN 'No' END AS registryclass_flagqualification,CASE WHEN registryclass.flagqualification_forced = 'S' THEN 'Si' WHEN registryclass.flagqualification_forced = 'N' THEN 'No' END AS registryclass_flagqualification_forced,CASE WHEN registryclass.flagresidence = 'S' THEN 'Si' WHEN registryclass.flagresidence = 'N' THEN 'No' END AS registryclass_flagresidence,CASE WHEN registryclass.flagresidence_forced = 'S' THEN 'Si' WHEN registryclass.flagresidence_forced = 'N' THEN 'No' END AS registryclass_flagresidence_forced,CASE WHEN registryclass.flagtitle = 'S' THEN 'Si' WHEN registryclass.flagtitle = 'N' THEN 'No' END AS registryclass_flagtitle,CASE WHEN registryclass.flagtitle_forced = 'S' THEN 'Si' WHEN registryclass.flagtitle_forced = 'N' THEN 'No' END AS registryclass_flagtitle_forced, registryclass.idregistryclass, registryclass.lt AS registryclass_lt, registryclass.lu AS registryclass_lu, isnull('Descrizione: ' + registryclass.description + '; ','') as dropdown_title FROM [dbo].registryclass WITH (NOLOCK)  WHERE  registryclass.active = 'S' AND registryclass.flaghuman = 'S' AND registryclass.idregistryclass IS NOT NULL 
GO

