-- VERIFICA DI registrydocentiview IN CUSTOMOBJECT --
IF EXISTS(select * from customobject where objectname = 'registrydocentiview')
UPDATE customobject set isreal = 'N' where objectname = 'registrydocentiview'
ELSE
