CREATE VIEW [dbo].[sostenimentoingressoview] AS SELECT  sostenimento.ct AS sostenimento_ct, sostenimento.cu AS sostenimento_cu, sostenimento.data AS sostenimento_data, sostenimento.domande AS sostenimento_domande, sostenimento.ects AS sostenimento_ects, sostenimento.giudizio AS sostenimento_giudizio, sostenimento.idappello AS sostenimento_idappello, sostenimento.idattivform AS sostenimento_idattivform, sostenimento.idcorsostudio, sostenimento.iddidprog, [dbo].iscrizione.anno AS iscrizione_anno, [dbo].iscrizione.iddidprog AS iscrizione_iddidprog, [dbo].annoaccademico.aa AS annoaccademico_aa, sostenimento.idiscrizione, sostenimento.idprova, [dbo].registry.title AS registry_title, sostenimento.idreg, sostenimento.idsostenimento, [dbo].sostenimentoesito.title AS sostenimentoesito_title, sostenimento.idsostenimentoesito AS sostenimento_idsostenimentoesito, sostenimento.idtitolostudio AS sostenimento_idtitolostudio, sostenimento.insecod AS sostenimento_insecod, sostenimento.insedesc AS sostenimento_insedesc,CASE WHEN sostenimento.livello = 'A' THEN 'A ' WHEN sostenimento.livello = 'B' THEN 'B ' WHEN sostenimento.livello = 'C' THEN 'C ' WHEN sostenimento.livello = 'D' THEN 'D ' END AS sostenimento_livello, sostenimento.lt AS sostenimento_lt, sostenimento.lu AS sostenimento_lu, sostenimento.paridsostenimento AS sostenimento_paridsostenimento, sostenimento.protanno AS sostenimento_protanno, sostenimento.protnumero AS sostenimento_protnumero, sostenimento.voto AS sostenimento_voto,CASE WHEN sostenimento.votolode = 'S' THEN 'Si' WHEN sostenimento.votolode = 'N' THEN 'No' END AS sostenimento_votolode, sostenimento.votosu AS sostenimento_votosu, isnull('Studente: ' + [dbo].registry.title + '; ','') + ' ' + isnull('Voto: ' + CAST( sostenimento.voto AS NVARCHAR(64)) + '; ','') + ' ' + isnull('Codice Anno accademico: ' + [dbo].annoaccademico.aa + '; ','') + ' ' + isnull('Su: ' + CAST( sostenimento.votosu AS NVARCHAR(64)) + '; ','') + ' ' + isnull('' + CASE WHEN sostenimento.votolode = 'S' THEN 'Lode' ELSE '' END,'') as dropdown_title FROM [dbo].sostenimento WITH (NOLOCK)  LEFT OUTER JOIN [dbo].iscrizione WITH (NOLOCK) ON sostenimento.idiscrizione = [dbo].iscrizione.idiscrizione LEFT OUTER JOIN [dbo].annoaccademico WITH (NOLOCK) ON iscrizione.aa = [dbo].annoaccademico.aa LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON sostenimento.idreg = [dbo].registry.idreg LEFT OUTER JOIN [dbo].sostenimentoesito WITH (NOLOCK) ON sostenimento.idsostenimentoesito = [dbo].sostenimentoesito.idsostenimentoesito WHERE  sostenimento.idcorsostudio IS NOT NULL  AND sostenimento.iddidprog IS NOT NULL  AND sostenimento.idprova IS NOT NULL  AND sostenimento.idreg IS NOT NULL  AND sostenimento.idsostenimento IS NOT NULL 
