EFT OUTER JOIN [dbo].sostenimentoesito WITH (NOLOCK) ON sostenimento.idsostenimentoesito = [dbo].sostenimentoesito.idsostenimentoesito WHERE  sostenimento.idcorsostudio IS NOT NULL  AND sostenimento.iddidprog IS NOT NULL  AND sostenimento.idiscrizione IS NOT NULL  AND sostenimento.idreg IS NOT NULL  AND sostenimento.idsostenimento IS NOT NULL 
