-- CREAZIONE VISTA strutturaseg_childview
IF EXISTS(select * from sysobjects where id = object_id(N'[strutturaseg_childview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [strutturaseg_childview]
GO

CREATE VIEW [strutturaseg_childview] AS SELECT  struttura.codice AS struttura_codice, struttura.codiceipa AS struttura_codiceipa, struttura.ct AS struttura_ct, struttura.cu AS struttura_cu, struttura.email AS struttura_email, struttura.fax AS struttura_fax, [dbo].aoo.title AS aoo_title, struttura.idaoo AS struttura_idaoo, [dbo].registry.title AS registry_title, struttura.idreg, [dbo].sede.title AS sede_title, struttura.idsede AS struttura_idsede, struttura.idstruttura, [dbo].strutturakind.title AS strutturakind_title, struttura.idstrutturakind, upb.title AS upb_title, struttura.idupb, struttura.lt AS struttura_lt, struttura.lu AS struttura_lu, struttura.telefono AS struttura_telefono, struttura.title AS struttura_title, struttura.title_en AS struttura_title_en, isnull('Tipologia: ' + [dbo].strutturakind.title + '; ','') + ' ' + isnull('Denominazione: ' + struttura.title + '; ','') as dropdown_title FROM [dbo].struttura WITH (NOLOCK)  LEFT OUTER JOIN [dbo].aoo WITH (NOLOCK) ON struttura.idaoo = [dbo].aoo.idaoo LEFT OUTER JOIN [dbo].registry WITH (NOLOCK) ON struttura.idreg = [dbo].registry.idreg LEFT OUTER JOIN [dbo].sede WITH (NOLOCK) ON struttura.idsede = [dbo].sede.idsede LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind LEFT OUTER JOIN upb WITH (NOLOCK) ON struttura.idupb = upb.idupb WHERE  struttura.idstruttura IS NOT NULL 
GO

