-- CREAZIONE VISTA tirociniopropostosegview
IF EXISTS(select * from sysobjects where id = object_id(N'[dbo].[tirociniopropostosegview]') and OBJECTPROPERTY(id, N'IsView') = 1)
DROP VIEW [dbo].[tirociniopropostosegview]
