CREATE VIEW [dbo].[tirociniopropostosegview] AS SELECT  tirocinioproposto.ct AS tirocinioproposto_ct, tirocinioproposto.cu AS tirocinioproposto_cu, tirocinioproposto.description AS tirocinioproposto_description, tirocinioproposto.description_en AS tirocinioproposto_description_en, [dbo].aoo.title AS aoo_title, tirocinioproposto.idaoo, registryreferente.title AS registryreferente_title, tirocinioproposto.idreg_referente, [dbo].struttura.title AS struttura_title, [dbo].strutturakind.title AS strutturakind_title, tirocinioproposto.idstruttura, tirocinioproposto.idtirocinioproposto, tirocinioproposto.lt AS tirocinioproposto_lt, tirocinioproposto.lu AS tirocinioproposto_lu, tirocinioproposto.ore AS tirocinioproposto_ore, tirocinioproposto.title, tirocinioproposto.title_en AS tirocinioproposto_title_en, isnull('Titolo: ' + tirocinioproposto.title + '; ','') + ' ' + isnull('Descrizione: ' + tirocinioproposto.description + '; ','') + ' ' + isnull('Tipologia Tipologia: ' + [dbo].strutturakind.title + '; ','') + ' ' + isnull('Descrizione in inglese: ' + tirocinioproposto.description_en + '; ','') as dropdown_title FROM [dbo].tirocinioproposto WITH (NOLOCK)  LEFT OUTER JOIN [dbo].aoo WITH (NOLOCK) ON tirocinioproposto.idaoo = [dbo].aoo.idaoo LEFT OUTER JOIN [dbo].registry AS registryreferente WITH (NOLOCK) ON tirocinioproposto.idreg_referente = registryreferente.idreg LEFT OUTER JOIN [dbo].struttura WITH (NOLOCK) ON tirocinioproposto.idstruttura = [dbo].struttura.idstruttura LEFT OUTER JOIN [dbo].strutturakind WITH (NOLOCK) ON struttura.idstrutturakind = [dbo].strutturakind.idstrutturakind WHERE  tirocinioproposto.idreg_referente IS NOT NULL  AND tirocinioproposto.idtirocinioproposto IS NOT NULL 
GO

